 |[[Social democracy]]|ref|{{Cite book |last=Szajkowski |first=Bogdan |title=Political parties of the world |date=2005 |publisher=J. Harper publ |isbn=978-0-9543811-4-1 |edition=6th |location=London |quote=The PSU was founded in 1910 and reorganized after themajority split away to form the Communist Party (PCU) in1921. The PSU moved to the left in 1959 and became a founder member of the Broad Front (FA) in 1971. Currently the party is divided between its more orthodox left-wing faction and the social-democrat modernizers.}}|</ref>|
 |[[Democratic socialism]]|ref|{{Cite thesis |last1=Tapia |first1=Morán |last2=Guillermina |first2=Juana |last3=Ramírez |first3=Vera |last4=Mirian |first4=Irene |date=April 2010 |title=Incidencias de las tendencias de los partidos políticos en los países latinoamericanos para la generación de riqueza y en el crecimiento económico, periodo 1990-2007. |url=https://repositorio.ucsg.edu.ec/handle/3317/9785 |publisher=[[Universidad Católica de Santiago de Guayaquil]] |archive-url= |archive-date= |quote=Partido Socialista del Uruguay, Socialismo Democratico |trans-quote=Socialist Party of Uruguay, Democratic Socialism }}|</ref>|}}

